    - { choose: 1, from: ["Literacy: Other", "Literacy: Euro", "Literacy: Russian", "Literacy: Gypsy"], bonus: 20, note: "Likely literate in one other language (+20%). 90% of Elves." }
    - { name: "Mathematics: Basic", base: 65, per_level: 5, note: "+20%. 90% of Elves." }
natural_abilities:
